using System;
using System.IO;
using System.Linq;
using MassiveArmy.Industrial;
static class GovernmentChecks {
 static int checks;static void Check(bool pass,string text){if(!pass)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
 static IndustrialCommand C(IndustrialWorld w,long actor,string kind,long source=0,long target=0,string text=null,long count=0,string operation=null)=>new IndustrialCommand{sequence=w.Actor(actor).lastSequence+1,kind=kind,source=source,target=target,item=text,count=count,operationRole=operation,pose=w.Actor(actor).pose};
 static CommandResult Send(IndustrialAuthority a,long actor,string kind,long source=0,long target=0,string text=null,long count=0,string operation=null)=>a.Execute(actor,C(a.World,actor,kind,source,target,text,count,operation));
 static long Found(IndustrialAuthority a,long actor,string name){Check(Send(a,actor,"tribe-create",text:name).accepted,"Actor "+actor+" founds "+name);return a.World.government.ForActor(actor).id;}
 static long Invite(IndustrialAuthority a,long actor,string kind,long target){var result=Send(a,actor,kind,target:target);Check(result.accepted,"Invitation accepted by authority: "+kind);return a.World.government.invitations.Last().id;}
 static void Main(){
  var data=new IndustrialWorld();for(int i=1;i<=12;i++)data.Register(i,new FramePose{body=1,y=10000});var g=data.government;string path=Path.GetFullPath("TestResults/Planetary/Government/recovery-"+Guid.NewGuid().ToString("N")+".xml");Directory.CreateDirectory(Path.GetDirectoryName(path));
  long alpha,beta,gamma,delta,epsilon;
  using(var authority=new IndustrialAuthority(data,path)){
   alpha=Found(authority,1,"Alpha");beta=Found(authority,2,"Beta");gamma=Found(authority,3,"Gamma");delta=Found(authority,4,"Delta");epsilon=Found(authority,5,"Epsilon");
   Check(!Send(authority,1,"tribe-create",text:"Duplicate").accepted&&g.tribes.Count==5,"One player cannot lead multiple independent tribes");Check(!Send(authority,6,"tribe-create",text:"alpha").accepted,"Tribe names are unique ignoring case");
   long memberInvite=Invite(authority,1,"tribe-invite-member",6);Check(!Send(authority,7,"tribe-respond",memberInvite,count:1).accepted,"Another player cannot accept a membership invitation");Check(Send(authority,6,"tribe-respond",memberInvite,count:1).accepted&&g.ForActor(6).id==alpha,"Invited player explicitly accepts membership");
   Check(!Send(authority,6,"tribe-invite-alliance",target:beta).accepted,"A member cannot negotiate diplomacy");Check(!Send(authority,6,"tribe-role",target:1,text:"Leader").accepted,"Members cannot promote themselves or replace the leader");
   Check(Send(authority,1,"tribe-role",target:6,text:"Officer").accepted,"Leader can appoint an officer");Check(g.CanGovern(6,alpha)&&!g.CanGovern(6,beta),"Officer jurisdiction ends at their own branch");Check(!Send(authority,6,"tribe-rule",text:"friendly-fire",count:1).accepted,"Officers cannot rewrite sovereign rules");
   long alliance=Invite(authority,1,"tribe-invite-alliance",beta);Check(!g.Allied(alpha,beta),"An unaccepted alliance proposal grants no treaty");Check(!Send(authority,3,"tribe-respond",alliance,count:1).accepted,"Only the receiving leader can accept diplomacy");
   var accept=C(data,2,"tribe-respond",alliance,count:1);Check(authority.Execute(2,accept).accepted&&g.Allied(alpha,beta),"Alliance acceptance creates equal bilateral protection");Check(!authority.Execute(2,accept).accepted&&g.alliances.Count==1,"Replay cannot duplicate a treaty");Check(!g.CanGovern(1,beta)&&!g.CanGovern(2,alpha),"Equal allies gain no management authority over each other");
   Check(!g.CanAttack(1,2)&&!g.CanAttack(2,6),"Allied members are mutually protected");Check(!g.CanAttack(1,6),"Same-realm friendly fire is disabled by default");Check(g.CanAttack(1,3),"Neutral realms remain distinct");
   double health=data.Actor(2).health;Check(authority.ApplyPlayerCombatDamage(1,2,1,20)!=null&&data.Actor(2).health==health,"Authoritative combat rejects allied hits without changing health");Check(!Send(authority,1,"tribe-damage",target:3,count:100).accepted,"Raw player commands cannot submit arbitrary combat damage");
   long bc=Invite(authority,2,"tribe-invite-alliance",gamma);Check(Send(authority,3,"tribe-respond",bc,count:1).accepted,"A second equal alliance can be accepted");Check(g.CanAttack(1,3),"Non-aggression is bilateral, not silently transitive");
   long absorb=Invite(authority,1,"tribe-invite-subject",beta);long items=data.Actor(2).inventory.Count("stone");Check(Send(authority,2,"tribe-respond",absorb,count:1).accepted&&g.Tribe(beta).parent==alpha,"Accepting subordination attaches the tribe beneath the inviter");Check(!g.Allied(beta,gamma)&&g.CanAttack(1,3),"A subject's previous independent alliances end");Check(data.Actor(2).inventory.Count("stone")==items,"Absorption preserves private inventory and identity");var disbandSubject=Send(authority,2,"tribe-disband");Check(!disbandSubject.accepted&&disbandSubject.message.Contains("release"),"Disband cannot bypass a subject realm’s secession restriction");Check(g.CanGovern(1,beta)&&!g.CanGovern(2,alpha),"Ruler orders flow down, never upwards");Check(!Send(authority,2,"tribe-invite-alliance",target:gamma).accepted,"Subjects cannot negotiate foreign policy around their ruler");
   long ag=Invite(authority,1,"tribe-invite-alliance",gamma);Check(Send(authority,3,"tribe-respond",ag,count:1).accepted&&!g.CanAttack(2,3),"Subject members inherit the ruling realm's alliances");
   var order=Send(authority,1,"tribe-order",alpha,text:"Defend the landing zone",count:1,operation:"Defend");Check(order.accepted&&g.orders.Last().recipients.Count==2,"Orders propagate to the selected tribe and all subject branches");long task=g.orders.Last().id;
   Check(!Send(authority,1,"tribe-order",gamma,text:"Obey me",operation:"Rally").accepted,"An equal ally cannot be ordered as a subordinate");Check(!Send(authority,1,"tribe-order",alpha,gamma,"Attack ally",operation:"Attack").accepted,"Attack directives cannot target allies");Check(!Send(authority,2,"tribe-order",alpha,text:"Order my ruler",operation:"Rally").accepted,"Subject leaders cannot issue orders to their ruler");
   Check(Send(authority,2,"tribe-order-status",task,text:"Acknowledged").accepted,"Recipient leadership can acknowledge an order");Check(Send(authority,2,"tribe-order-status",task,text:"Completed").accepted,"Recipient leadership can complete its own receipt");Check(!Send(authority,2,"tribe-order-status",task,text:"Acknowledged").accepted,"Completed receipts cannot move backwards");Check(!Send(authority,2,"tribe-order-cancel",task).accepted,"Recipients cannot cancel the sovereign's order for everyone");Check(!Send(authority,1,"tribe-order-archive",task).accepted,"An unresolved active order cannot be silently archived");
   Check(Send(authority,1,"tribe-rule",text:"officer-construction",count:1).accepted,"Sovereign publishes inherited construction policy");long invite7=Invite(authority,2,"tribe-invite-member",7);Check(Send(authority,7,"tribe-respond",invite7,count:1).accepted,"A subject can retain and recruit its own members");Check(data.ConstructionPolicyError(7)!=null&&data.ConstructionPolicyError(2)==null,"Inherited policy restricts members while retaining local leadership permission");
   var place=C(data,7,"place");place.definition="generator";place.pose=data.Actor(7).pose;Check(!authority.Execute(7,place).accepted&&data.machines.Count==0,"Restricted members cannot place machinery through raw authoritative commands");bool blocked=false;try{authority.CommitConstructionResources(7,1,"{}",new System.Collections.Generic.List<ItemStack>(),false,null,null);}catch(InvalidOperationException){blocked=true;}Check(blocked,"Trusted base construction commits enforce the same inherited policy");
   Check(Send(authority,1,"tribe-rule",text:"officer-combat",count:1).accepted&&data.CombatPolicyError(7)!=null,"Combat authorization follows the sovereign's rule");Check(authority.ApplyPlayerCombatDamage(7,4,1,10)!=null,"Combat hit authority rejects an unauthorized member");
   Check(!Send(authority,2,"tribe-secede").accepted,"Subject cannot freely bypass a no-secession rule");Check(Send(authority,1,"tribe-rule",text:"allow-secession",count:1).accepted&&Send(authority,2,"tribe-secede").accepted,"Sovereign can permit voluntary independence");Check(g.Tribe(beta).parent==0&&g.OrderLive(g.orders.First(o=>o.id==task)),"An order with a still-owned root recipient remains managed by its issuer");Check(!g.OrderVisible(2,g.orders.First(o=>o.id==task)),"A former subject cannot see or act on its old ruler's directive");
   long ab2=Invite(authority,1,"tribe-invite-subject",beta);Check(Send(authority,2,"tribe-respond",ab2,count:1).accepted,"Independent former subject can consent to rejoin");
   long ad=Invite(authority,1,"tribe-invite-subject",delta);Check(Send(authority,4,"tribe-respond",ad,count:1).accepted,"A second branch can join the realm");long ae=Invite(authority,1,"tribe-invite-subject",epsilon);Check(Send(authority,5,"tribe-respond",ae,count:1).accepted,"A third branch can join the realm");
   Check(Send(authority,1,"tribe-reparent",delta,beta).accepted&&g.Tribe(delta).parent==beta,"Sovereign can delegate a subject branch beneath another subject");Check(!Send(authority,1,"tribe-reparent",beta,delta).accepted,"Reparenting cannot create a hierarchy cycle");
   Check(Send(authority,1,"tribe-order",delta,text:"Guard Delta",operation:"Defend").accepted,"A ruler can assign a focused subject order");var revoke=g.orders.Last();Check(Send(authority,1,"tribe-release",beta).accepted&&!g.OrderLive(revoke),"Releasing a branch revokes commands that no longer have jurisdiction");Check(g.Tribe(delta).parent==beta&&g.Root(g.Tribe(delta)).id==beta,"Release preserves the subject's subordinate structure");
   Check(Send(authority,1,"tribe-break-alliance",target:gamma).accepted&&g.CanAttack(1,3),"Ending an alliance removes non-aggression immediately");Check(authority.ApplyPlayerCombatDamage(1,3,1,20)==null&&data.Actor(3).health==80,"Neutral combat damage goes through the trusted hit boundary");Check(authority.ApplyPlayerCombatDamage(1,3,1,20)!=null&&data.Actor(3).health==80,"Combat sequence prevents replayed damage");
   Check(!Send(authority,1,"tribe-test-create",text:"Phantom").accepted,"Test tribes cannot be created outside creative mode");Check(Send(authority,1,"creative",count:1).accepted,"Creative test mode can be explicitly enabled");Check(Send(authority,1,"tribe-test-create",text:"Creative North").accepted,"Creative host can create a data-only independent test tribe");var test=g.tribes.Last();long invitation=Invite(authority,1,"tribe-invite-subject",test.id);Check(!Send(authority,1,"tribe-respond",invitation,count:1).accepted,"Creative mode does not impersonate ordinary invitation responses");Check(Send(authority,1,"tribe-test-respond",invitation,count:1).accepted&&test.parent==alpha,"Explicit creative response is limited to a marked test leader");Check(!Send(authority,1,"tribe-test-respond",Invite(authority,1,"tribe-invite-subject",gamma),count:1).accepted,"Creative test controls cannot force a real player's tribe to submit");
   long lone=Found(authority,9,"Lone Tribe");Check(Send(authority,9,"tribe-order",lone,text:"Wait at base",operation:"Rally").accepted,"A one-player tribe can issue its own persistent task");long loneTask=g.orders.Last().id;var disbandOrder=Send(authority,9,"tribe-disband");Check(!disbandOrder.accepted&&disbandOrder.message.Contains("Archive"),"Disband cannot orphan an issued order board");Check(Send(authority,9,"tribe-order-cancel",loneTask).accepted&&Send(authority,9,"tribe-order-archive",loneTask).accepted&&Send(authority,9,"tribe-disband").accepted,"Resolved orders can be archived before an explicit disband");
   authority.Save();Check(Send(authority,1,"tribe-standing-orders",text:"Protect the mining site and respect all treaties.").accepted,"Post-snapshot policy change is journaled");Check(authority.ApplyPlayerCombatDamage(1,3,2,5)==null,"Post-snapshot combat event is journaled");
  }
  var recovered=IndustrialAuthority.Load(path);Check(recovered.government.Tribe(beta).parent==0&&recovered.government.Tribe(delta).parent==beta,"Recovery preserves nested organizational identity");Check(recovered.government.Tribe(alpha).rules.standingOrders.Contains("mining site")&&recovered.Actor(3).health==75,"Journal recovery restores policy and applies combat damage once");Check(recovered.Actor(1).playerCombatSequence==2,"Recovery retains hit replay protection");var copy=IndustrialAuthority.Restore(IndustrialAuthority.Snapshot(recovered));Check(copy.government.revision==recovered.government.revision&&copy.government.orders.Count==recovered.government.orders.Count,"Snapshot roundtrip preserves diplomacy and order receipts");
  var old=IndustrialAuthority.Restore("<IndustrialWorld><version>1</version><nextId>1</nextId></IndustrialWorld>");Check(old.government!=null&&old.government.tribes.Count==0,"Older survival snapshots initialize empty governance safely");
  var depthWorld=new IndustrialWorld();for(int i=1;i<=9;i++)depthWorld.Register(i,new FramePose{body=1});using(var authority=new IndustrialAuthority(depthWorld)){
   var ids=new long[10];for(int i=1;i<=9;i++)ids[i]=Found(authority,i,"Depth "+i);
   for(int i=8;i>=2;i--){long invitation=Invite(authority,i,"tribe-invite-subject",ids[i+1]);Check(Send(authority,i+1,"tribe-respond",invitation,count:1).accepted,"Nested consent attaches branch at depth "+(10-i));}
   long tooDeep=Invite(authority,1,"tribe-invite-subject",ids[2]);Check(!Send(authority,2,"tribe-respond",tooDeep,count:1).accepted&&depthWorld.government.Tribe(ids[2]).parent==0,"Acceptance rejects a ninth hierarchy level without partial mutation");
   Check(!Send(authority,1,"tribe-rename",text:"Bad\0Name").accepted,"Control characters are rejected before journal serialization");
   Check(Send(authority,2,"tribe-rule",text:"friendly-fire",count:1).accepted&&depthWorld.government.CanAttack(2,3),"Sovereign can explicitly permit same-realm friendly fire");
  }
  File.WriteAllText("TestResults/Planetary/Government/model-summary.json","{\"status\":\"PASS\",\"checks\":"+checks+"}");Console.WriteLine(checks+" governance checks passed");
 }
}
